package com.metalurgica.sistemagestaoindustrial.importacao;

import org.apache.poi.ss.usermodel.*; import org.apache.poi.xssf.usermodel.XSSFWorkbook; import org.springframework.stereotype.Component; import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.math.BigDecimal; import java.text.Normalizer; import java.time.*; import java.time.format.*; import java.util.*;

@Component public class ExcelImportReader {
 private static final List<String> REQUIRED=List.of("funcionario","peca","quantidade","data","inicio","fim");
 private static final Map<String,List<String>> ALIASES=Map.of("funcionario",List.of("funcionario","codfuncionario","codigofuncionario","matricula","codfunc"),"peca",List.of("peca","codpeca","codigopeca","codigodapeca"),"quantidade",List.of("quantidade","qtd","qtde"),"data",List.of("data","dataproducao","dia"),"inicio",List.of("inicio","horarioinicio","horainicio","horaentrada"),"fim",List.of("fim","horariofim","horafim","horasaida"),"setor",List.of("setor","codigosetor"),"maquina",List.of("maquina","codigomaquina","recurso"),"turno",List.of("turno","codigoturno"));
 public ExcelReadResult read(MultipartFile file) {
  if(file==null||file.isEmpty()) throw new IllegalArgumentException("ARQUIVO_VAZIO"); if(file.getOriginalFilename()==null||!file.getOriginalFilename().toLowerCase(Locale.ROOT).endsWith(".xlsx")) throw new IllegalArgumentException("FORMATO_NAO_SUPORTADO");
  try(InputStream in=file.getInputStream(); Workbook wb=new XSSFWorkbook(in)){ DataFormatter fmt=new DataFormatter(Locale.ROOT); Sheet sheet=null; Map<String,Integer> headers=null; for(Sheet s:wb){var h=findHeaders(s,fmt); if(h!=null){sheet=s;headers=h;break;}} if(sheet==null) throw new IllegalArgumentException("CABECALHO_AUSENTE");
   List<LinhaProducaoImportada> rows=new ArrayList<>(); List<ImportacaoLinhaErro> errors=new ArrayList<>(); int headerRow=findHeaderRow(sheet,fmt,headers); int last=Math.min(sheet.getLastRowNum(),headerRow+10000); for(int n=headerRow+1;n<=last;n++){Row row=sheet.getRow(n); if(empty(row,fmt)) continue; int line=n+1; String func=text(row,headers.get("funcionario"),fmt),peca=text(row,headers.get("peca"),fmt); try { var qty=decimal(row,headers.get("quantidade"),fmt); var date=date(row,headers.get("data"),fmt); var start=time(row,headers.get("inicio"),fmt); var end=time(row,headers.get("fim"),fmt); if(func==null||func.isBlank()) throw error("codigoFuncionario","FUNCIONARIO_AUSENTE","Código de funcionário obrigatório."); if(peca==null||peca.isBlank()) throw error("codigoPeca","PECA_AUSENTE","Código de peça obrigatório."); if(qty==null||qty.signum()<=0) throw error("quantidade","QUANTIDADE_INVALIDA","Quantidade deve ser maior que zero."); if(date==null) throw error("data","DATA_INVALIDA","Data inválida."); if(start==null||end==null) throw error("horario","HORARIO_INVALIDO","Horário inválido."); boolean overnight=end.isBefore(start); rows.add(new LinhaProducaoImportada(line,func.trim(),peca.trim(),qty,date,start,end,text(row,headers.get("setor"),fmt),text(row,headers.get("maquina"),fmt),text(row,headers.get("turno"),fmt))); } catch(ParseError e){errors.add(new ImportacaoLinhaErro(line,e.field,e.code,e.getMessage(),func,peca));} }
   return new ExcelReadResult(rows,errors,rows.size()+errors.size());
  } catch(IllegalArgumentException e){throw e;} catch(Exception e){throw new IllegalArgumentException("ARQUIVO_CORROMPIDO");}
 }
 private Map<String,Integer> findHeaders(Sheet s,DataFormatter f){for(int r=0;r<=Math.min(s.getLastRowNum(),10);r++){Row row=s.getRow(r);if(row==null)continue;Map<String,Integer> map=new HashMap<>();for(Cell c:row){String h=norm(f.formatCellValue(c));for(var entry:ALIASES.entrySet())if(entry.getValue().contains(h))map.putIfAbsent(entry.getKey(),c.getColumnIndex());}if(map.keySet().containsAll(REQUIRED))return map;}return null;}
 private int findHeaderRow(Sheet s,DataFormatter f,Map<String,Integer> h){for(int r=0;r<=Math.min(s.getLastRowNum(),10);r++){Row row=s.getRow(r);if(row!=null&&norm(f.formatCellValue(row.getCell(h.get("funcionario")))).length()>0)return r;}return 0;}
 private static String norm(String v){return Normalizer.normalize(v==null?"":v,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
 private static boolean empty(Row r,DataFormatter f){if(r==null)return true;for(Cell c:r)if(!f.formatCellValue(c).isBlank())return false;return true;}
 private static String text(Row r,Integer i,DataFormatter f){return i==null||r==null||r.getCell(i)==null?null:f.formatCellValue(r.getCell(i)).trim();}
 private static BigDecimal decimal(Row r,int i,DataFormatter f){String v=text(r,i,f);if(v==null||v.isBlank())return null;try{String normalized=v.replace(" ","");if(normalized.contains(",")&&normalized.contains("."))normalized=normalized.replace(".","").replace(',','.');else if(normalized.contains(","))normalized=normalized.replace(',','.');return new BigDecimal(normalized);}catch(Exception e){throw error("quantidade","QUANTIDADE_INVALIDA","Quantidade inválida.");}}
 private static LocalDate date(Row r,int i,DataFormatter f){Cell c=r.getCell(i);try{if(c!=null&&c.getCellType()==CellType.NUMERIC&&DateUtil.isCellDateFormatted(c))return c.getLocalDateTimeCellValue().toLocalDate();String v=text(r,i,f);if(v==null)return null;String[] a=v.contains("/")?v.split("/"):v.split("-");if(a.length!=3)return null;if(v.contains("/"))return LocalDate.of(Integer.parseInt(a[2]),Integer.parseInt(a[1]),Integer.parseInt(a[0]));return LocalDate.of(Integer.parseInt(a[0]),Integer.parseInt(a[1]),Integer.parseInt(a[2]));}catch(Exception e){return null;}}
 private static LocalTime time(Row r,int i,DataFormatter f){Cell c=r.getCell(i);try{if(c!=null&&c.getCellType()==CellType.NUMERIC&&DateUtil.isCellDateFormatted(c))return c.getLocalDateTimeCellValue().toLocalTime();String v=text(r,i,f);if(v==null)return null;for(String p:List.of("H:mm","H:mm:ss"))try{return LocalTime.parse(v,DateTimeFormatter.ofPattern(p));}catch(Exception ignored){}return null;}catch(Exception e){return null;}}
 private static ParseError error(String field,String code,String msg){return new ParseError(field,code,msg);} private static class ParseError extends RuntimeException{final String field,code;ParseError(String f,String c,String m){super(m);field=f;code=c;}}
}
